use crate::ranfile::types::{RanFormat, RanTarget, Ranfile, RanfileOut};
use crate::t;
use anyhow::{Context, Result};
use colored::Colorize;
use std::collections::HashSet;
use std::path::{Path, PathBuf};

/// Target names reserved for `ran` subcommands — cannot be used in a ranfile.
pub(crate) const RESERVED_TARGET_NAMES: &[&str] =
    &["init", "deinit", "help", "list", "ls", "check", "fmt"];

/// Default ranfile name (TOML).
pub(crate) const RANFILE_NAME: &str = "NTCRANFILE.toml";

/// Default ranfile template generated by `ran init`.
pub(crate) const RANFILE_TEMPLATE: &str = r##"# NTCRANFILE — ntc task runner configuration
# Usage:
#   ran            → runs [targets.standalone]
#   ran <name>    → runs a specific target
#   ran list      → lists all targets
#   ran init      → creates this file
#   ran check     → validates this file and points at problems
#   ran fmt <fmt> → converts this file to toml / json / yaml
#   ran help    → shows full usage with examples

# ── Variables ──────────────────────────────────────────────────────────
# Define variables here and reference them with $(VAR_NAME) in commands.
# Variables can reference other variables (up to 10 levels of nesting).
#
# Example:
#   CC     = "gcc"
#   FLAGS  = "-Wall -O2"
#   OUTDIR = "dist"
#   ver    = "2.3.0"
#   major  = "2"
#   minor  = "3"
#   version = "$(major).$(minor)"  # expands to "2.3"
#
# Then use them: cmd = "$(CC) $(FLAGS) main.c -o $(OUTDIR)/app"

[vars]
# CC = "gcc"
# FLAGS = "-O2"
# ver = "2.3.0"

# ── Targets ────────────────────────────────────────────────────────────
# Each target can have:
#   deps — list of other targets that must run first
#   cmd  — shell command to execute (goes through ntc's alias system, so
#          run aliases, @teleports, and system commands all work)

[targets]

[targets.standalone]
# Default target — runs when `ran` is typed without arguments
deps = []
cmd = "echo 'Hello from ran!'"

# [targets.build]
# deps = ["lint"]
# cmd = "echo Building..."

# [targets.lint]
# deps = []
# cmd = "ruff check ."

# [targets.test]
# deps = ["build"]
# cmd = "echo Running tests..."

# [targets.clean]
# deps = []
# cmd = "rm -rf *.o dist/"
"##;

/// YAML starter file: the same shape as the TOML template, comments included.
pub(crate) const RANFILE_YAML_TEMPLATE: &str = r##"# NTCRANFILE — ntc task runner configuration
# Usage:
#   ran            -> runs the `standalone` target
#   ran <name>     -> runs a specific target
#   ran list       -> lists all targets
#   ran init       -> creates this file
#   ran check      -> validates this file and points at problems
#   ran fmt <fmt>  -> converts this file to toml / json / yaml
#
# Variables are expanded with $(VAR_NAME) inside commands, and `deps`
# targets run before the target that lists them (in order).

vars: {}
#   CC: gcc
#   FLAGS: -O2

targets:
  standalone:
    deps: []
    cmd: "echo 'Hello from ran!'"
  # build:
  #   deps: [lint]
  #   cmd: "echo Building..."
  # lint:
  #   deps: []
  #   cmd: "ruff check ."
"##;

/// Every file name a ranfile may live under, for error messages.
pub(crate) fn ranfile_names() -> String {
    let mut names: Vec<&str> = Vec::new();
    for fmt in RanFormat::ALL {
        for name in fmt.file_names() {
            names.push(name);
        }
    }
    names.join(", ")
}

/// Format `ran init` should create (last `ran fmt`, TOML by default).
pub(crate) fn preferred_format() -> RanFormat {
    RanFormat::parse(&crate::utils::config::Config::global_get_ran_format())
        .unwrap_or(RanFormat::Toml)
}

/// Find the ranfile in `dir`, trying the preferred format first.
///
/// Preferring the format the user last converted to means `ran fmt yaml`
/// takes effect immediately, even while the old `.toml` is still on disk.
pub(crate) fn resolve(dir: &Path) -> Option<(PathBuf, RanFormat)> {
    let preferred = preferred_format();
    let mut order = vec![preferred];
    order.extend(RanFormat::ALL.into_iter().filter(|fmt| *fmt != preferred));
    for fmt in order {
        for name in fmt.file_names() {
            let path = dir.join(name);
            if path.is_file() {
                return Some((path, fmt));
            }
        }
    }
    None
}

/// Parse the ranfile in `dir`, whatever its format.
pub(crate) fn parse(path: &Path) -> Result<Ranfile> {
    let Some((file, _)) = resolve(path) else {
        anyhow::bail!(
            "No ranfile ({}) found in {}",
            ranfile_names(),
            path.display()
        );
    };
    parse_file(&file)
}

/// Parse one explicit ranfile, dispatching on its extension.
pub(crate) fn parse_file(path: &Path) -> Result<Ranfile> {
    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(RANFILE_NAME);
    let fmt = RanFormat::from_path(path)
        .with_context(|| format!("Unsupported ranfile format: {}", name))?;
    let content =
        std::fs::read_to_string(path).with_context(|| format!("Cannot read {}", path.display()))?;
    parse_text(&content, fmt).with_context(|| format!("Failed to parse {}", name))
}

/// Parse ranfile text in a known format and validate it.
pub(crate) fn parse_text(content: &str, fmt: RanFormat) -> Result<Ranfile> {
    let ranfile: Ranfile = match fmt {
        RanFormat::Toml => toml::from_str(content).context("invalid TOML")?,
        RanFormat::Json => serde_json::from_str(content).context("invalid JSON")?,
        RanFormat::Yaml => serde_yaml::from_str(content).context("invalid YAML")?,
    };
    validate(ranfile)
}

/// Write `ranfile` as `fmt`. Keys are sorted so conversions stay diffable.
pub(crate) fn render(ranfile: &Ranfile, fmt: RanFormat) -> Result<String> {
    let out = RanfileOut::from_ranfile(ranfile);
    let mut body = match fmt {
        RanFormat::Toml => toml::to_string_pretty(&out).context("failed to write TOML")?,
        RanFormat::Json => serde_json::to_string_pretty(&out).context("failed to write JSON")?,
        RanFormat::Yaml => serde_yaml::to_string(&out).context("failed to write YAML")?,
    };
    if !body.ends_with('\n') {
        body.push('\n');
    }
    Ok(body)
}

/// Starter file body for `ran init`.
pub(crate) fn template(fmt: RanFormat) -> Result<String> {
    match fmt {
        RanFormat::Toml => Ok(RANFILE_TEMPLATE.to_string()),
        RanFormat::Yaml => Ok(RANFILE_YAML_TEMPLATE.to_string()),
        RanFormat::Json => render(&default_ranfile(), RanFormat::Json),
    }
}

/// The task graph a fresh JSON ranfile starts from.
fn default_ranfile() -> Ranfile {
    let mut targets = std::collections::HashMap::new();
    targets.insert(
        "standalone".to_string(),
        RanTarget {
            deps: Vec::new(),
            cmd: "echo 'Hello from ran!'".to_string(),
        },
    );
    Ranfile {
        vars: std::collections::HashMap::new(),
        targets,
    }
}

/// Expand variables, then reject every structurally unusable ranfile.
fn validate(ranfile: Ranfile) -> Result<Ranfile> {
    // Expand variables within the vars section itself (recursive expansion)
    let mut expanded_vars = ranfile.vars.clone();
    expand_vars_in_map(&mut expanded_vars);

    // Create a new Ranfile with expanded vars
    let ranfile = Ranfile {
        vars: expanded_vars,
        targets: ranfile.targets,
    };

    // Validate: at least one target
    if ranfile.targets.is_empty() {
        anyhow::bail!("the ranfile has no targets");
    }

    // Validate: no reserved names
    for name in ranfile.targets.keys() {
        if RESERVED_TARGET_NAMES.contains(&name.as_str()) {
            anyhow::bail!(
                "'{}' is a reserved name and cannot be used as a target",
                name
            );
        }
    }

    // Validate all referenced dependencies exist
    for (name, target) in &ranfile.targets {
        for dep in &target.deps {
            if !ranfile.targets.contains_key(dep) {
                anyhow::bail!(
                    "Target '{}' depends on '{}' but '{}' is not defined",
                    name,
                    dep,
                    dep
                );
            }
        }
    }

    // Check for circular dependencies
    for name in ranfile.targets.keys() {
        let mut visited = HashSet::new();
        if detect_cycle(name, &ranfile.targets, &mut visited) {
            anyhow::bail!("Circular dependency detected involving target '{}'", name);
        }
    }

    Ok(ranfile)
}

/// Expand $(VAR) references within a HashMap of variables.
fn expand_vars_in_map(vars: &mut std::collections::HashMap<String, String>) {
    // Multiple passes to handle chained references (a = "$(b)", b = "1" → a = "1")
    for _ in 0..10 {
        let snapshot = vars.clone();
        let mut changed = false;
        for (_key, value) in vars.iter_mut() {
            let expanded = expand_vars(value, &snapshot);
            if expanded != *value {
                *value = expanded;
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
}

/// Expand $(VAR_NAME) references in a string.
fn expand_vars(s: &str, vars: &std::collections::HashMap<String, String>) -> String {
    let mut result = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '$' && chars.peek() == Some(&'(') {
            chars.next(); // consume '('
            let mut var_name = String::new();
            let mut found_close = false;
            for c in chars.by_ref() {
                if c == ')' {
                    found_close = true;
                    break;
                }
                var_name.push(c);
            }
            if found_close {
                let expanded = vars.get(&var_name).map(|s| s.as_str()).unwrap_or("");
                result.push_str(expanded);
            } else {
                // Unclosed $( — preserve the literal text
                result.push_str("$(");
                result.push_str(&var_name);
            }
        } else {
            result.push(ch);
        }
    }

    result
}

/// Check whether a dependency cycle exists starting from `target`.
fn detect_cycle(
    target: &str,
    targets: &std::collections::HashMap<String, RanTarget>,
    visited: &mut HashSet<String>,
) -> bool {
    if !visited.insert(target.to_string()) {
        return true;
    }
    if let Some(t) = targets.get(target) {
        for dep in &t.deps {
            if detect_cycle(dep, targets, visited) {
                return true;
            }
        }
    }
    visited.remove(target);
    false
}

/// Print a friendly list of all targets and their dependencies.
pub(crate) fn list_targets(ranfile: &Ranfile) {
    let mut names: Vec<&String> = ranfile.targets.keys().collect();
    names.sort();

    println!("{}", t!("ranfile.available_title").cyan().bold());
    println!();
    for name in names {
        let target = &ranfile.targets[name];
        let dep_str = if target.deps.is_empty() {
            String::new()
        } else {
            format!("{}{}", t!("ranfile.depends_on"), target.deps.join(", "))
        };
        println!("  {}{}", name.green(), dep_str.yellow());

        // Show the actual command (with variables expanded), indented below the target.
        if !target.cmd.is_empty() {
            let cmd = expand_vars(&target.cmd, &ranfile.vars);
            println!("    {}", cmd.dimmed());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const GRAPH: &str = r#"
[vars]
ver = "1.0"
arc = "app-$(ver).zip"

[targets.standalone]
deps = []
cmd = "echo $(arc)"

[targets.build]
deps = ["lint"]
cmd = "echo build"

[targets.lint]
deps = []
cmd = "echo lint"
"#;

    fn target_names(ranfile: &Ranfile) -> Vec<String> {
        let mut names: Vec<String> = ranfile.targets.keys().cloned().collect();
        names.sort();
        names
    }

    #[test]
    fn every_format_round_trips_the_same_graph() {
        let toml_ranfile = parse_text(GRAPH, RanFormat::Toml).expect("toml");
        let expected = target_names(&toml_ranfile);
        assert_eq!(expected, vec!["build", "lint", "standalone"]);
        assert_eq!(toml_ranfile.vars["arc"], "app-1.0.zip");
        assert_eq!(toml_ranfile.targets["build"].deps, vec!["lint"]);

        for fmt in [RanFormat::Json, RanFormat::Yaml] {
            let body = render(&toml_ranfile, fmt).expect("render");
            let back = parse_text(&body, fmt).expect("re-parse");
            assert_eq!(target_names(&back), expected, "{} lost targets", fmt.ext());
            assert_eq!(back.vars["arc"], "app-1.0.zip");
            assert_eq!(back.targets["build"].deps, vec!["lint"]);
            assert_eq!(back.targets["standalone"].cmd, "echo $(arc)");
        }
    }

    #[test]
    fn json_and_yaml_templates_parse_back() {
        for fmt in RanFormat::ALL {
            let body = template(fmt).expect("template");
            let ranfile = parse_text(&body, fmt).expect("template must parse");
            assert!(ranfile.targets.contains_key("standalone"), "{}", fmt.ext());
        }
    }

    #[test]
    fn rendered_output_has_sorted_targets_and_a_final_newline() {
        let ranfile = parse_text(GRAPH, RanFormat::Toml).expect("toml");
        let body = render(&ranfile, RanFormat::Json).expect("json");
        assert!(body.ends_with('\n'));
        let build = body.find("\"build\"").expect("build");
        let lint = body.find("\"lint\"").expect("lint");
        let standalone = body.find("\"standalone\"").expect("standalone");
        assert!(build < lint && lint < standalone, "not sorted:\n{body}");
    }

    #[test]
    fn formats_map_to_their_file_names_and_extensions() {
        assert_eq!(RanFormat::parse("YML"), Some(RanFormat::Yaml));
        assert_eq!(RanFormat::parse("toml"), Some(RanFormat::Toml));
        assert_eq!(RanFormat::parse("xml"), None);
        assert_eq!(RanFormat::Yaml.file_name(), "NTCRANFILE.yaml");
        assert_eq!(RanFormat::Json.ext(), "json");
        assert_eq!(
            RanFormat::from_path(Path::new("/x/NTCRANFILE.yml")),
            Some(RanFormat::Yaml)
        );
    }

    #[test]
    fn fmt_is_a_reserved_target_name() {
        assert!(RESERVED_TARGET_NAMES.contains(&"fmt"));
        let body = "[targets.fmt]\ncmd = \"echo hi\"\n";
        assert!(parse_text(body, RanFormat::Toml).is_err());
    }
}
